"""Display-only rendering of user macros and LaTeX typography."""
import unittest

from researchtool.latex_display import collect_macros, prettify

DEFINITIONS = r"""
% Generated by make_figures.py
\newcommand{\previewWithMin}{31.2}
\newcommand{\previewWithMax}{33.5}
\newcommand\previewWithoutMin{29.0}
\def\previewWithoutMax{\num{30.4}}
\renewcommand{\nImages}{1,610}
\providecommand{\nImages}{9999}
\newcommand{\nScenes}{\nImages\xspace}
\newcommand{\gain}[0]{$-28.7$}
\newcommand{\twoArgs}[2]{#1 and #2}
\def\withParam#1{x#1}
% \newcommand{\commented}{nope}
\newcommand{\escaped}{50\%}
"""


class LatexDisplayTests(unittest.TestCase):
    def setUp(self):
        self.macros = collect_macros([DEFINITIONS])

    def test_collects_zero_argument_definitions_only(self):
        self.assertEqual(self.macros["previewWithMin"], "31.2")
        self.assertEqual(self.macros["previewWithoutMin"], "29.0")
        self.assertEqual(self.macros["previewWithoutMax"], r"\num{30.4}")
        self.assertEqual(self.macros["nImages"], "1,610")  # \providecommand never overrides
        self.assertEqual(self.macros["gain"], "$-28.7$")
        for name in ("twoArgs", "withParam", "commented"):
            self.assertNotIn(name, self.macros)

    def test_user_examples_render_numbers_and_typography(self):
        self.assertEqual(prettify(r"\previewWithMin -- \previewWithMax \, dB", self.macros), "31.2–33.5 dB")
        self.assertEqual(prettify(r"\previewWithoutMin -- \previewWithoutMax \, dB（ 0.05和0.5 bpp 之间）", self.macros),
                         "29.0–30.4 dB（ 0.05和0.5 bpp 之间）")

    def test_tex_spacing_rules_citations_refs_and_math(self):
        self.assertEqual(prettify(r"\nImages images; \nImages{} images; \nScenes scenes", self.macros),
                         "1,610images; 1,610 images; 1,610 scenes")
        self.assertEqual(prettify(r"codecs~\cite{a2018,b2019} (Fig.~\ref{fig:main}) gain \gain\ at \escaped",
                                  self.macros), "codecs [a2018, b2019] (Fig. ‹fig:main›) gain -28.7 at 50%")
        self.assertEqual(prettify(r"\SI{0.05}{bpp} and $x_1 + y$ and \unknown{}", self.macros),
                         "0.05 bpp and x₁ + y and \\unknown{}")
        self.assertEqual(prettify(r"less than $32^2$ px, AP$_{\text{tiny}}$, $\tau=0.02$, $a^b$", self.macros),
                         r"less than 32² px, AP_tiny, $\tau=0.02$, $a^b$")

    def test_fpeval_arithmetic_is_safe_and_labels_hidden(self):
        macros = {**self.macros, "tuned": "-39.7", "a": "0.1", "b": "0.2"}
        self.assertEqual(prettify(r"with \fpeval{0 - (\tuned)}\% fewer bits", macros), "with 39.7% fewer bits")
        self.assertEqual(prettify(r"\fpeval{\a + \b}", macros), "0.3")
        self.assertEqual(prettify(r"\fpeval{round(100*(1-4.58/8.72),0)}\% below", macros), "47% below")
        self.assertEqual(prettify(r"\fpeval{round(2.5)} \fpeval{max(1, abs(-4))}", macros), "3 4")
        self.assertEqual(prettify(r"\fpeval{exec(1)}", macros), r"\fpeval{exec(1)}")
        for unsafe in (r"\fpeval{__import__(1)}", r"\fpeval{2^999}", r"\fpeval{1/0}", r"\fpeval{\undefined + 1}"):
            self.assertEqual(prettify(unsafe, macros), unsafe)
        self.assertEqual(prettify(r"Introduction\label{sec:intro} starts", macros), "Introduction starts")

    def test_idempotent_and_cycle_safe(self):
        macros = {**self.macros, "loopA": r"\loopB", "loopB": r"\loopA"}
        for text in (r"\previewWithMin -- \previewWithMax \, dB", r"see~\cite{x}", r"\loopA"):
            once = prettify(text, macros)
            self.assertEqual(prettify(once, macros), once)
        self.assertEqual(prettify("中文没有命令。", macros), "中文没有命令。")


if __name__ == "__main__":
    unittest.main()
